/* A OnePage address can never be somebody else's name, whoever writes it (round AW, lead's own fix). storelib.me/{name} answers a page whose address (slug) is the name BEFORE the page of the account whose username is the name (lib/onepage/resolve-address.ts), so a page given another account's username as its address takes that person's storelib.me link, their share card and their old /links addresses. The app's save route refuses that (app/api/onepage/route.ts with lib/onepage/name-availability.ts onePageNameTaken: another page's address in any case, or another account's username), but the owner policy on onepages lets a signed in account write its own row's slug straight through the public API, past that check. Now a write with the browser key (anon or authenticated) that sets or changes a page's address to one another page already has in any case, or to another account's username in any case, is refused with the same unique violation (23505) the route already answers as "That address is taken". The server (service role) is not checked here, the route checks it. A save that leaves the address as it is is never checked, so pages made before these rules still save, and no existing row is changed or read back. The helper public.storelib_onepage_address_taken(text, uuid, uuid) runs with its owner's rights and says only whether a name is taken, which the public profiles and pages already show. Safe to run again. */
CREATE OR REPLACE FUNCTION public.storelib_onepage_address_taken(p_slug text, p_page uuid, p_owner uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $f$ SELECT p_slug IS NOT NULL AND btrim(p_slug) <> '' AND (EXISTS (SELECT 1 FROM public.onepages o WHERE lower(o.slug) = lower(btrim(p_slug)) AND (p_page IS NULL OR o.id <> p_page)) OR EXISTS (SELECT 1 FROM public.profiles p WHERE lower(p.username) = lower(btrim(p_slug)) AND (p_owner IS NULL OR p.id <> p_owner))) $f$;
REVOKE ALL ON FUNCTION public.storelib_onepage_address_taken(text, uuid, uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.storelib_onepage_address_taken(text, uuid, uuid) TO authenticated, service_role;
CREATE OR REPLACE FUNCTION public.onepages_address_not_anothers() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $f$ BEGIN IF current_user NOT IN ('authenticated', 'anon') THEN RETURN NEW; END IF; IF NEW.slug IS NULL THEN RETURN NEW; END IF; IF TG_OP = 'UPDATE' AND lower(coalesce(NEW.slug, '')) = lower(coalesce(OLD.slug, '')) THEN RETURN NEW; END IF; IF public.storelib_onepage_address_taken(NEW.slug, NEW.id, NEW.owner_id) THEN RAISE EXCEPTION 'That page address is taken' USING ERRCODE = '23505'; END IF; RETURN NEW; END $f$;
REVOKE ALL ON FUNCTION public.onepages_address_not_anothers() FROM PUBLIC, anon, authenticated;
DO $do$ BEGIN IF to_regclass('public.onepages') IS NULL OR to_regclass('public.profiles') IS NULL THEN RAISE NOTICE 'part 460: public.onepages or public.profiles does not exist here, skipped'; RETURN; END IF; IF (SELECT count(*) FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'onepages' AND column_name IN ('slug', 'owner_id')) < 2 OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'profiles' AND column_name = 'username') THEN RAISE NOTICE 'part 460: onepages.slug, onepages.owner_id or profiles.username is missing here, skipped'; RETURN; END IF; DROP TRIGGER IF EXISTS onepages_address_not_anothers ON public.onepages; CREATE TRIGGER onepages_address_not_anothers BEFORE INSERT OR UPDATE OF slug ON public.onepages FOR EACH ROW EXECUTE FUNCTION public.onepages_address_not_anothers(); END $do$;
notify pgrst, 'reload schema';
